type AppearanceRow = [
  key: string,
  name: string,
  nameEn: string,
  group: string,
  groupEn: string,
  def: string,
  defEn: string,
  ontologyLevel?: ConceptBaseItem['ontologyLevel'],
  eras?: ConceptEra[],
  subjectScope?: ConceptSubjectScope[],
  risk?: ConceptBaseItem['risk'],
  affects?: string[]
];

const makeItems = (prefix: string, rows: AppearanceRow[], defaultAffects: string[]): ConceptBaseItem[] =>
  rows.map(([key, name, nameEn, group, groupEn, def, defEn, ontologyLevel = 1, eras = ALL_REAL_ERAS, subjectScope = UNIVERSAL_HUMAN_SCOPE, risk = 'clean', affects = defaultAffects]) => ({
    id: `cd_${prefix}_${key}`,
    name,
    nameEn,
    group,
    groupEn,
    def,
    defEn,
    subjectScope,
    ontologyLevel,
    eras,
    affects,
    risk
  }));

